  ["HUD_EDIT_MODE_UNSAVED_CHANGES_LAYOUT_CHANGE_DIALOG_TITLE"] = { "レイアウトを切り替えると、保存していない変更は失われます。|nどうしますか？", 0x48153f70, "." },
